#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

int main(int argc, char *argv[]) {
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }
    char *end;
    // Parse base
    errno = 0;
    long long base = strtoll(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Parse exponent
    errno = 0;
    long long exp = strtoll(argv[2], &end, 10);
    if (end == argv[2] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Parse modulus
    errno = 0;
    long long mod = strtoll(argv[3], &end, 10);
    if (end == argv[3] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (mod <= 0) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }
    // Reduce base modulo mod and make it non‑negative
    long long b = base % mod;
    if (b < 0) b += mod;
    // Compute (b^exp) mod mod using binary exponentiation with 128‑bit intermediate
    long long result = 1 % mod;
    unsigned long long e = (unsigned long long)exp;
    while (e) {
        if (e & 1ULL) {
            __int128 tmp = ( __int128) result * b;
            result = (long long)(tmp % mod);
        }
        __int128 tmp = ( __int128) b * b;
        b = (long long)(tmp % mod);
        e >>= 1ULL;
    }
    printf("result=%lld\n", result);
    return 0;
}
